# FIXME: remove this. Python has introduced ConnectionError builtin.
class ConnectionError(Exception):
    """Base class for all internal exceptions related to Connection class."""


class ConnectFailedError(ConnectionError):
    """A ``connect()`` subroutine failed."""


class CommandExecutionError(ConnectionError):
    """A ``send_command()`` subroutine failed."""


class CommandOutputCollectionError(ConnectionError):
    """Output collection subroutine failed."""


class CommandOutputTimeoutError(ConnectionError):
    """Timed out while reading process output."""

    def __init__(self, message=None, output_so_far=None):
        super().__init__(message, output_so_far)

        self.message = message
        self.output_so_far = output_so_far

    def __str__(self):
        return self.message


class CommandOutputCollectionTerminationError(
    CommandOutputTimeoutError, CommandOutputCollectionError
):
    """Reading output of a process stopped prematurely."""


class FileProtocolClientError(ConnectionError):
    """Initializing a :py:class:`FileProtocol` instance failed.

    For Robot Framework file transfer keywords, this is also raised when a
    local file is not found / wrong type.
    """
